//! "Chapters & bookmarks": a collapsible strip above the meeting transcript
//! (issue #87).
//!
//! Chapters are generated by `parley_core::chapters` (on demand from the
//! button here, or automatically after a recording) and bookmarks are the
//! moments marked while recording (`parley_core::bookmarks`). Both lists are
//! clickable: a click emits [`MomentsEvent::JumpTo`], which the meeting page
//! answers by scrolling the transcript to that moment. Bookmark labels can
//! be added or edited here; bookmarks can be deleted.
//!
//! Chapter titles are LLM output and so untrusted: the core parser already
//! reduces them to short plain text, and this view only ever renders them
//! as plain text — never markdown, never a link.
//!
//! [`MomentsPanel::transcript_markers`] tells the transcript which rows to
//! mark with a chapter heading or a bookmark flag.

use std::collections::HashMap;

use gpui_kit::component::{
    ActiveTheme, Disableable as _, Icon,
    button::{Button, ButtonVariants as _},
    h_flex,
    input::{Input, InputEvent, InputState},
    v_flex,
};
use gpui_kit::base::StyledExt as _;
use gpui_kit::component::Sizable as _;
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;
use parley_core::bookmarks::{
    self, BookmarksChanged, BookmarksRepository, MeetingBookmark, BOOKMARKS_CHANGED_EVENT,
};
use parley_core::chapters::{self, ChaptersRepository, MeetingChapter, CHAPTERS_EVENT};
use parley_core::chat::context::format_timestamp;
use parley_core::database::models::MeetingTranscript;

use super::format;
use crate::app_state::AppServices;
use crate::runtime::Io;

type Lucide = gpui_kit::assets::IconName;

/// Tallest the expanded strip gets before it scrolls.
const BODY_MAX_HEIGHT: Pixels = px(220.);

pub enum MomentsEvent {
    /// A chapter or bookmark was clicked: show the transcript at this time.
    JumpTo(f64),
}

impl EventEmitter<MomentsEvent> for MomentsPanel {}

/// What to draw on one transcript row.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct SegmentMarkers {
    /// Chapters starting at this row (normally at most one).
    pub chapters: Vec<String>,
    /// Bookmarks mapped to this row: their labels, `None` when unlabelled.
    pub bookmarks: Vec<Option<String>>,
}

/// Map chapters (by start time — the row they begin at) and bookmarks (to
/// their nearest segment) onto transcript row ids.
pub fn build_markers(
    chapters: &[MeetingChapter],
    bookmarks: &[MeetingBookmark],
    transcripts: &[MeetingTranscript],
) -> HashMap<String, SegmentMarkers> {
    let mut out: HashMap<String, SegmentMarkers> = HashMap::new();
    for chapter in chapters {
        if let Some(ix) = format::transcript_index_for_time(transcripts, chapter.start_seconds) {
            out.entry(transcripts[ix].id.clone())
                .or_default()
                .chapters
                .push(chapter.title.clone());
        }
    }
    for bookmark in bookmarks {
        if let Some(ix) = bookmarks::nearest_transcript_index(transcripts, bookmark.offset_seconds) {
            out.entry(transcripts[ix].id.clone())
                .or_default()
                .bookmarks
                .push(bookmark.label.clone());
        }
    }
    out
}

/// The chapter heading(s) and bookmark flag(s) drawn at the top of a
/// transcript row. Plain text only.
pub fn render_row_markers(markers: &SegmentMarkers, cx: &App) -> AnyElement {
    v_flex()
        .w_full()
        .gap_1()
        .children(markers.chapters.iter().map(|title| {
            h_flex()
                .gap_2()
                .items_center()
                .pt_1()
                .text_color(cx.theme().primary)
                .child(Icon::from(Lucide::ListOrdered).xsmall())
                .child(div().text_sm().font_semibold().child(SharedString::from(title.clone())))
        }))
        .when(!markers.bookmarks.is_empty(), |this| {
            this.child(
                h_flex()
                    .gap_2()
                    .flex_wrap()
                    .children(markers.bookmarks.iter().map(|label| {
                        h_flex()
                            .gap_1()
                            .items_center()
                            .px_1p5()
                            .rounded(cx.theme().radius)
                            .bg(cx.theme().warning.opacity(0.15))
                            .text_xs()
                            .child(Icon::from(Lucide::Bookmark).xsmall().text_color(cx.theme().warning))
                            .child(SharedString::from(
                                label.clone().unwrap_or_else(|| "Bookmarked".to_string()),
                            ))
                    })),
            )
        })
        .into_any_element()
}

pub struct MomentsPanel {
    meeting_id: Option<String>,
    /// Bumped on every `set_meeting`; stale async completions compare it.
    generation: u64,
    chapters: Vec<MeetingChapter>,
    bookmarks: Vec<MeetingBookmark>,
    generating: bool,
    error: Option<String>,
    collapsed: bool,
    /// The bookmark whose label is being edited, if any.
    editing: Option<String>,
    label_input: Entity<InputState>,
    _subscriptions: Vec<Subscription>,
}

impl MomentsPanel {
    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
        let label_input = cx.new(|cx| InputState::new(window, cx).placeholder("Label (optional)"));
        let core_events = AppServices::global(cx).core_events.clone();
        let subscriptions = vec![
            cx.subscribe_in(&label_input, window, |this, _, event: &InputEvent, _window, cx| {
                if let InputEvent::PressEnter { .. } = event {
                    this.save_label(cx);
                }
            }),
            cx.subscribe(&core_events, |this, _, event, cx| {
                if event.name == BOOKMARKS_CHANGED_EVENT {
                    if let Some(payload) = event.decode::<BookmarksChanged>() {
                        if this.meeting_id.as_deref() == Some(payload.meeting_id.as_str()) {
                            this.reload(cx);
                        }
                    }
                } else if event.name == CHAPTERS_EVENT {
                    this.on_chapters_event(event, cx);
                }
            }),
        ];
        Self {
            meeting_id: None,
            generation: 0,
            chapters: Vec::new(),
            bookmarks: Vec::new(),
            generating: false,
            error: None,
            collapsed: false,
            editing: None,
            label_input,
            _subscriptions: subscriptions,
        }
    }

    /// Show `id`'s chapters and bookmarks (called on every meeting load).
    pub fn set_meeting(&mut self, id: String, cx: &mut Context<Self>) {
        self.generation += 1;
        self.generating = chapters::is_generating(&id);
        self.meeting_id = Some(id);
        self.chapters.clear();
        self.bookmarks.clear();
        self.error = None;
        self.editing = None;
        self.reload(cx);
    }

    pub fn transcript_markers(
        &self,
        transcripts: &[MeetingTranscript],
    ) -> HashMap<String, SegmentMarkers> {
        build_markers(&self.chapters, &self.bookmarks, transcripts)
    }

    fn reload(&mut self, cx: &mut Context<Self>) {
        let Some(id) = self.meeting_id.clone() else { return };
        let Some(pool) = AppServices::global(cx).pool() else { return };
        let io = Io::global(cx);
        let generation = self.generation;
        cx.spawn(async move |this, cx| {
            let result = io
                .spawn(async move {
                    let chapters = ChaptersRepository::list_by_meeting(&pool, &id).await?;
                    let bookmarks = BookmarksRepository::list_by_meeting(&pool, &id).await?;
                    Ok::<_, sqlx::Error>((chapters, bookmarks))
                })
                .await;
            let _ = this.update(cx, |this, cx| {
                if this.generation != generation {
                    return;
                }
                match result {
                    Ok(Ok((chapters, bookmarks))) => {
                        this.chapters = chapters;
                        this.bookmarks = bookmarks;
                    }
                    Ok(Err(e)) => this.error = Some(format!("Failed to load chapters: {e}")),
                    Err(e) => this.error = Some(format!("Failed to load chapters: {e}")),
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn on_chapters_event(&mut self, event: &crate::core_events::CoreEvent, cx: &mut Context<Self>) {
        #[derive(serde::Deserialize)]
        struct Payload {
            meeting_id: String,
            status: String,
            error: Option<String>,
        }
        let Some(payload) = event.decode::<Payload>() else { return };
        if self.meeting_id.as_deref() != Some(payload.meeting_id.as_str()) {
            return;
        }
        match payload.status.as_str() {
            "running" => {
                self.generating = true;
                self.error = None;
            }
            "done" => {
                self.generating = false;
                self.reload(cx);
            }
            _ => {
                self.generating = false;
                self.error = payload.error;
            }
        }
        cx.notify();
    }

    fn generate(&mut self, cx: &mut Context<Self>) {
        let Some(id) = self.meeting_id.clone() else { return };
        if self.generating {
            return;
        }
        let Some(pool) = AppServices::global(cx).pool() else { return };
        let sink = AppServices::global(cx).sink.clone();
        self.generating = true;
        self.error = None;
        self.collapsed = false;
        cx.notify();
        // Progress and the result arrive as `CHAPTERS_EVENT`s (the same
        // path an automatic post-recording run reports through).
        Io::global(cx).spawn(async move {
            let _ = chapters::generate_chapters(sink, pool, id).await;
        });
    }

    fn start_edit(&mut self, bookmark: &MeetingBookmark, window: &mut Window, cx: &mut Context<Self>) {
        self.editing = Some(bookmark.id.clone());
        let value = bookmark.label.clone().unwrap_or_default();
        self.label_input.update(cx, |s, cx| {
            s.set_value(value, window, cx);
            s.focus(window, cx);
        });
        cx.notify();
    }

    fn cancel_edit(&mut self, cx: &mut Context<Self>) {
        self.editing = None;
        cx.notify();
    }

    fn save_label(&mut self, cx: &mut Context<Self>) {
        let (Some(id), Some(meeting_id)) = (self.editing.take(), self.meeting_id.clone()) else {
            return;
        };
        let Some(pool) = AppServices::global(cx).pool() else { return };
        let sink = AppServices::global(cx).sink.clone();
        let label = self.label_input.read(cx).value().to_string();
        // Show it straight away; the change event reloads the stored form.
        if let Some(b) = self.bookmarks.iter_mut().find(|b| b.id == id) {
            b.label = bookmarks::sanitize_label(&label);
        }
        cx.notify();
        Io::global(cx).spawn(async move {
            if let Err(e) = bookmarks::rename_bookmark(sink, pool, meeting_id, id, label).await {
                log::warn!("{e}");
            }
        });
    }

    fn delete_bookmark(&mut self, id: String, cx: &mut Context<Self>) {
        let Some(meeting_id) = self.meeting_id.clone() else { return };
        let Some(pool) = AppServices::global(cx).pool() else { return };
        let sink = AppServices::global(cx).sink.clone();
        self.bookmarks.retain(|b| b.id != id);
        if self.editing.as_deref() == Some(id.as_str()) {
            self.editing = None;
        }
        cx.notify();
        Io::global(cx).spawn(async move {
            if let Err(e) = bookmarks::delete_bookmark(sink, pool, meeting_id, id).await {
                log::warn!("{e}");
            }
        });
    }

    fn time_label(seconds: f64, cx: &App) -> Div {
        div()
            .flex_none()
            .text_xs()
            .font_family(cx.theme().mono_font_family.clone())
            .text_color(cx.theme().muted_foreground)
            .child(format_timestamp(seconds))
    }

    fn render_chapter_row(&self, ix: usize, chapter: &MeetingChapter, cx: &mut Context<Self>) -> AnyElement {
        let seconds = chapter.start_seconds;
        h_flex()
            .id(("chapter-row", ix))
            .w_full()
            .gap_2()
            .px_2()
            .py_1()
            .rounded(cx.theme().radius)
            .cursor_pointer()
            .hover(|s| s.bg(cx.theme().muted.opacity(0.5)))
            .child(Self::time_label(seconds, cx))
            // Plain text only: an LLM-written title is never rendered as
            // markdown or a link.
            .child(div().flex_1().min_w_0().text_sm().truncate().child(SharedString::from(chapter.title.clone())))
            .on_click(cx.listener(move |_, _, _, cx| cx.emit(MomentsEvent::JumpTo(seconds))))
            .into_any_element()
    }

    fn render_bookmark_row(&self, ix: usize, bookmark: &MeetingBookmark, cx: &mut Context<Self>) -> AnyElement {
        let seconds = bookmark.offset_seconds;
        let id = bookmark.id.clone();
        if self.editing.as_deref() == Some(bookmark.id.as_str()) {
            return h_flex()
                .w_full()
                .gap_2()
                .px_2()
                .py_1()
                .child(Icon::from(Lucide::Bookmark).xsmall().text_color(cx.theme().warning))
                .child(Self::time_label(seconds, cx))
                .child(div().flex_1().child(Input::new(&self.label_input).xsmall()))
                .child(
                    Button::new(("bookmark-save", ix))
                        .xsmall()
                        .primary()
                        .label("Save")
                        .on_click(cx.listener(|this, _, _, cx| this.save_label(cx))),
                )
                .child(
                    Button::new(("bookmark-cancel", ix))
                        .xsmall()
                        .ghost()
                        .label("Cancel")
                        .on_click(cx.listener(|this, _, _, cx| this.cancel_edit(cx))),
                )
                .into_any_element();
        }

        let label: SharedString = bookmark
            .label
            .clone()
            .map(SharedString::from)
            .unwrap_or_else(|| "Bookmark".into());
        let unlabelled = bookmark.label.is_none();
        let for_edit = bookmark.clone();
        h_flex()
            .w_full()
            .gap_1()
            .child(
                h_flex()
                    .id(("bookmark-row", ix))
                    .flex_1()
                    .min_w_0()
                    .gap_2()
                    .px_2()
                    .py_1()
                    .rounded(cx.theme().radius)
                    .cursor_pointer()
                    .hover(|s| s.bg(cx.theme().muted.opacity(0.5)))
                    .child(Icon::from(Lucide::Bookmark).xsmall().text_color(cx.theme().warning))
                    .child(Self::time_label(seconds, cx))
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .text_sm()
                            .truncate()
                            .when(unlabelled, |d| d.text_color(cx.theme().muted_foreground))
                            .child(label),
                    )
                    .on_click(cx.listener(move |_, _, _, cx| cx.emit(MomentsEvent::JumpTo(seconds)))),
            )
            .child(
                Button::new(("bookmark-edit", ix))
                    .ghost()
                    .xsmall()
                    .icon(Lucide::Pencil)
                    .tooltip("Edit label")
                    .on_click(cx.listener(move |this, _, window, cx| this.start_edit(&for_edit, window, cx))),
            )
            .child(
                Button::new(("bookmark-delete", ix))
                    .ghost()
                    .xsmall()
                    .icon(Lucide::Trash)
                    .tooltip("Delete bookmark")
                    .on_click(cx.listener(move |this, _, _, cx| this.delete_bookmark(id.clone(), cx))),
            )
            .into_any_element()
    }
}

impl Render for MomentsPanel {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let has_chapters = !self.chapters.is_empty();
        let summary = match (self.chapters.len(), self.bookmarks.len()) {
            (0, 0) => "Chapters".to_string(),
            (c, 0) => format!("Chapters ({c})"),
            (0, b) => format!("Chapters · Bookmarks ({b})"),
            (c, b) => format!("Chapters ({c}) · Bookmarks ({b})"),
        };

        let header = h_flex()
            .w_full()
            .items_center()
            .gap_2()
            .px_2()
            .py_1()
            .child(
                h_flex()
                    .id("moments-toggle")
                    .flex_1()
                    .gap_1()
                    .items_center()
                    .cursor_pointer()
                    .child(Icon::from(if self.collapsed { Lucide::ChevronRight } else { Lucide::ChevronDown }).xsmall())
                    .child(div().text_sm().font_semibold().child(summary))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.collapsed = !this.collapsed;
                        cx.notify();
                    })),
            )
            .child(
                Button::new("generate-chapters")
                    .ghost()
                    .xsmall()
                    .icon(if has_chapters { Lucide::RefreshCw } else { Lucide::ListOrdered })
                    .label(if self.generating {
                        "Generating…"
                    } else if has_chapters {
                        "Regenerate"
                    } else {
                        "Generate chapters"
                    })
                    .loading(self.generating)
                    .disabled(self.generating || self.meeting_id.is_none())
                    .tooltip("Split the transcript into topic chapters with the summary model")
                    .on_click(cx.listener(|this, _, _, cx| this.generate(cx))),
            );

        let mut body = v_flex()
            .id("moments-body")
            .w_full()
            .max_h(BODY_MAX_HEIGHT)
            .overflow_y_scroll()
            .px_2()
            .pb_2()
            .gap_0p5();
        if let Some(err) = &self.error {
            body = body.child(div().px_2().text_xs().text_color(cx.theme().danger).child(err.clone()));
        }
        if has_chapters {
            let rows: Vec<AnyElement> = self
                .chapters
                .iter()
                .enumerate()
                .map(|(ix, c)| self.render_chapter_row(ix, c, cx))
                .collect();
            body = body.children(rows);
        } else if !self.generating {
            body = body.child(
                div()
                    .px_2()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("No chapters yet. Generate them to navigate the meeting by topic."),
            );
        }
        if !self.bookmarks.is_empty() {
            body = body.child(
                div()
                    .px_2()
                    .pt_2()
                    .text_xs()
                    .font_semibold()
                    .text_color(cx.theme().muted_foreground)
                    .child("Bookmarks"),
            );
            let rows: Vec<AnyElement> = self
                .bookmarks
                .clone()
                .iter()
                .enumerate()
                .map(|(ix, b)| self.render_bookmark_row(ix, b, cx))
                .collect();
            body = body.children(rows);
        }

        v_flex()
            .w_full()
            .border_b_1()
            .border_color(cx.theme().border)
            .child(header)
            .when(!self.collapsed, |this| this.child(body))
    }
}

#[cfg(test)]
mod tests {
    // Not `super::*`: that glob brings in `gpui_kit::*`'s `test` attribute,
    // which shadows the std one.
    use super::build_markers;
    use parley_core::bookmarks::MeetingBookmark;
    use parley_core::chapters::MeetingChapter;
    use parley_core::database::models::MeetingTranscript;

    fn seg(id: &str, start: f64, end: f64) -> MeetingTranscript {
        MeetingTranscript {
            id: id.into(),
            text: "x".into(),
            timestamp: "x".into(),
            audio_start_time: Some(start),
            audio_end_time: Some(end),
            duration: None,
            speaker: None,
            voice_profile_id: None,
            source: None,
            confidence: None,
        }
    }

    fn chapter(start: f64, title: &str) -> MeetingChapter {
        MeetingChapter {
            id: title.into(),
            meeting_id: "m".into(),
            position: 0,
            start_seconds: start,
            title: title.into(),
            created_at: "x".into(),
        }
    }

    fn bookmark(offset: f64, label: Option<&str>) -> MeetingBookmark {
        MeetingBookmark {
            id: "b".into(),
            meeting_id: "m".into(),
            offset_seconds: offset,
            label: label.map(str::to_string),
            created_at: "x".into(),
        }
    }

    #[test]
    fn markers_land_on_the_right_rows() {
        let transcripts = vec![seg("a", 0.0, 9.0), seg("b", 10.0, 19.5), seg("c", 30.0, 40.0)];
        let markers = build_markers(
            &[chapter(0.0, "Intro"), chapter(30.0, "Budget")],
            &[bookmark(12.0, Some("Key")), bookmark(24.0, None), bookmark(26.0, None)],
            &transcripts,
        );
        assert_eq!(markers["a"].chapters, vec!["Intro".to_string()]);
        assert!(markers["a"].bookmarks.is_empty());
        // In the gap: 24s is closer to b's end (19.5) than c's start (30);
        // 26s is closer to c.
        assert_eq!(markers["b"].bookmarks, vec![Some("Key".to_string()), None]);
        assert_eq!(markers["c"].chapters, vec!["Budget".to_string()]);
        assert_eq!(markers["c"].bookmarks, vec![None]);
        assert!(build_markers(&[chapter(0.0, "X")], &[bookmark(1.0, None)], &[]).is_empty());
    }
}
